import os, re, json

def load_grids():
    """Load all grids from session history"""
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    try:
        sessions_file = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
    except:
        return {}

    G = {}
    # Extract demo pairs
    demo_pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    matches = re.finditer(demo_pattern, sessions_file)

    for m in matches:
        k = m[1]
        h, w = int(m[2]), int(m[3])
        rows = [r.split() for r in sessions_file[m.end():].split('\n')[:h]]
        grid = [[int(x) for x in r] for r in rows if r.strip()]
        if k not in G and grid and len(grid) == h and all(len(r) == w for r in grid):
            G[k] = grid

    return G

G = load_grids()
print("Keys:", sorted(G.keys()))
for k, g in G.items():
    print(f"\n{k} ({len(g)}x{len(g[0])}):")
    for row in g:
        print(row)

